def calculate_contacts(n, queries, start, front_queue1, front_queue2, back_queue1, back_queue2):
    last_k_contacts = []
    for _, x, y in front_queue1:
        if x == y:
            last_k_contacts.append((x, len(last_k_contacts) + front_queue2[y-1]))
        elif x - y == -1:
            last_k_contacts.append((x, front_queue2[y-1] - front_queue2[x-1] - 1))
        elif y - x == -1:
            last_k_contacts.append((y, front_queue2[x-1] - front_queue2[y-1] - 1))

    # Adjust last_k_contacts to remove duplicates and correct for overlaps
    last_k_contacts = sorted(last_k_contacts, key=lambda x: x[1])
    front_contacts, i = [], 0
    while front_contacts and last_k_contacts[i][1] == last_k_contacts[0][1]:
        front_contacts.append(last_k_contacts.pop(0)[0])
        i += 1
    fill_contacts, j = [], 0
    while fill_contacts and last_k_contacts[j][1] == last_k_contacts[i][1]:
        fill_contacts.append(last_k_contacts.pop(0)[0])
        j += 1
