from collections import defaultdict, deque

def bfs(graph, source):
    visited = [False] * len(graph)
    queue = deque([source])
    visited[source] = True
    current_level = [source]
    next_level = []

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
                current_level.append(neighbor)
                next_level.append(neighbor)

    return current_level, next_level

def addToGraph(graph, edges):
    for edge in edges:
        a, b = edge
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append(b)
        graph[b].append(a)

def calCurrentResult(nextLevel):
    return (len(nextLevel) - 1) * (len(nextLevel) - 2) // 2

def addToEdges(graph, edges, result):
    for edge in edges:
        a, b = edge
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append(b)
        graph[b].append(a)
    result[0] += len(nextLevel)

def addToUnknown(w, max_index, graph, result):
    if max_index in graph:
        for neighbor in graph[max_index]:
            if neighbor > w:
                addToEdges(graph, [(w, neighbor)], result)
            if neighbor < w:
                addToEdges(graph, [(neighbor, w)], result)
    else:
        addToEdges(graph, [(w, max_index)], result)

def main():
    n, m = map(int, input().split())
    edges = []
    for _ in range(m):
        a, b = map(int, input().split())
        edges.append((a, b))

    n, q = map(int, input().split())
    target = list(map(int, input().split()))

    graph = defaultdict(list)
    result = [0]
    for element in edges:
        addToGraph(graph, [element])
    addToEdges(graph, [(target[0], n + q + 1)], result)

    for day in target[1:]:
        current_level, next_level = bfs(graph, day)
        addToUnknown(day, next_level[-1], graph, result)
        addToEdges(graph, [(day, next_level[0])], result)
        addToUnknown(n + q + 1, next_level[-1], graph, result)
        qday = calCurrentResult(next_level)
        result.append(qday)

    for res in result:
        print(res)

if __name__ == "__main__":
    main()
