from collections import defaultdict

def find_parent(parent, vertex):
    if parent[vertex] != vertex:
        parent[vertex] = find_parent(parent, parent[vertex])
    return parent[vertex]

def union_parent(parent, r1, r2):
    r1 = find_parent(parent, r1)
    r2 = find_parent(parent, r2)
    if r1 < r2:
        parent[r2] = r1
    else:
        parent[r1] = r2

def calculate_game_duration(n, edges, parent, chip_count, chip_positions):
    for u, v in edges:
        union_parent(parent, u, v)

    turns = [0] * n
    for chip in chip_positions:
        node = find_parent(parent, chip)
        turns[node - 1] += 1

    current_position = 0
    for i in range(n):
        if current_position == chip_count:
            break
        if turns[i] == n:
            current_position += 1
        turns[i] = n - current_position

    return turns

