import collections
import heapq

def min_perishability(mall_pos, delayed_later):
    n = len(mall_pos)
    x_list = collections.defaultdict(list)
    lazyness = 0

    for i in range(n, -1, -1):
        x_list[0].append((i, 0))
        lazyness = max(lazyness, mall_pos[i])

        for j in range(6):
            y = delayed_later[j] + lazyness
            x_list[j+1].append((i, y))

    # print(x_list)

    heap = [(0, 0)]
    dp = {}
    for i in range(n, -1, -1):
        loop = []
        while heap:
            z, k = heapq.heappop(heap)
            if k - 1 < i:
                break
            for y in x_list[k]:
                if dp.get(z+(y[0], need(z, y[0])), -1) != -1:
                    continue
                q, r = y[0], y[1]
                if q < n:
                    if dp.get(q, -1) == -1:
                        dp[q] = min_perishability(dp[q], mall_pos[q]) + r
                        if len(loop) < 6:
                            heapq.heappush(loop, (dp[q], q))

    ans = float('inf')
    for k in range(1, 6):
        ans = min(ans, dp.get(k, 10**6))

    return ans

def need(q, k):
    if q & (1 << k):
        return 0
    return 1

def ans(mall_pos):
    delayed_later = [i << 10 for i in range(len(mall_pos))]
    for i in range(12, -1, -1):
        delayed_later[i] = max(delayed_later[i], delayed_later[i^1] // 2)
        delayed_later[i] = min(delayed_later[i], delayed_later[i+1] + delayed_later[i-(i>>1) << i])
    return min_perishability(mall_pos, delayed_later)
