import sys

def find_minimum_measure(n, depths, inbounds, taxable):
    minimum_measures = [sys.maxsize] * n
    next_inbounds, near_inbounds = find_next(n, depths, inbounds)

    while next_inbounds != []:
        for destination, measure in next_inbounds.items():
            payment = 0
            # Include pool contributions up to taxable limit
            for i in range(0, 3):
                index = destination + i
                if index >= 0 and index < n:
                    payment += depths[index] * 100
            # Check nearby inbounds for penalties if applicable
            for i in range(0, 3):
                target = destination + i
                if near_inbounds[target] != -1:
                    payment += taxable
                    break
            # Compare with the smallest measured value
            if minimum_measures[destination] > measure:
                minimum_measures[destination] = measure

        # Move forward to the next fluid from initialization
        next_inbounds, near_inbounds = find_next(n, depths, inbounds)

    return minimum_measures

def find_next(n, depths, inbounds):
    near_inbounds = [-1] * n
    next_inbounds = {}
    for index in range(n):
        destination = sum([inbounds[depths[index]] for depth in range(0, 2)])
        if destination < n:
            next_inbounds[destination] = depths[index]
        near_inbounds[destination] = index
    return (next_inbounds, near_inbounds)

