def beauty_matrix_mod(input_n, input_matrix):
    mod = 998244353
    checker = [[0]*(1<<i) for i in range(input_n+1)]
    checker[0][1<<0] = 1
    for i in range(1, input_n+1):
        for j in range(1<<i):
            for k in range(i-1, -1, -1):
                checker[i][1<<i] ^= (j & (1<<k))
        for j in range(1<<i):
            for k in range(i-1, -1, -1):
                checker[i][j | (1<<i)] ^= (j & (1<<k))
    res = 0
    for i in range(1<<input_n):
        temp = i
        for j in range(input_n):
            temp &= 1 << ((input_n-j-1) - checker[input_n][i ^ (1<<j)])
        if temp == 0:
            res += 1
    return res%mod

