        dp[(p, c)] = 0
        for a, b in sorted(((s - p, c - b), (s - b, c - a))):
            if a <= 0 or b <= 0:
                continue
            dp[(p, c)] = max(dp[(p, c)], b * w + find(a, n, p, c, w, dp))
    return dp[(p, c)]

