def parse_input():
    import sys
    input = lambda: sys.stdin.readline().rstrip("\r\n")
    n, *a = map(int, input().split())
    return n, a


def create_matrix(a):
    return [[a[i * 3 + j] for j in range(len(a) // 3)] for i in range(len(a) // 3)]


def intersects(i, j, a, b):
    return a[i] == b[i] or a[i] == b[j] or b[i] == a[j]


def dfs(row, a):
    if row == len(a) // 3:
        return None
    overlap = False
    for i in range(row + 1, len(a)):
        i_row = a[i][0]
        for j in range(i + 1, len(a)):
            j_row = a[i][1]
            if i_row != j_row:
                if intersects(row, i, a, a[i:]):
                    overlap = True
                    pre = dfs(i, a)
                    if pre:
                        yield pre + [i_row]
                if not overlap and intersects(j, i, a, a[i]):
                    overlap = True
                    pre = dfs(i, a)
                    if pre:
                        yield pre + [i_row, j_row]
                if overlap and (isinstance(pre, list) and pre[-1] == i_row or isinstance(pre, list) and pre[-1] == j_row):
                    yield pre + [i_row, j_row]

    if overlap:
        yield [-1]
    else:
        yield [None]


def rarity(n, a):
    if n & 1 == 0:
        return 0

    a = create_matrix(a)
    maxima = [max(x) for x in a]

    result = 1
    p = 998244353

    low, high = *[value for value in [min(x) for x in maxima]]
    difference = pow(2, (high - low) * (n + 1) - 1, p)

    a.sort()

    a.reverse()

    a = create_matrix(a)

    max_case = list(dfs(-1, a))

    # 0 is the worst situation
    # we have the column numbered 2*n
    if max_case and max_case[0] == [-1]:
        return 0

    result = (difference - 1) * (n + 1) * pow(2, n, p) + 1
    return (result - pow(p, n, p)) % p


