from collections import defaultdict
import sys

def dijsktra(graph, start):
    n = len(graph)
    distances = {i: float('inf') for i in range(n)}
    distances[start] = 0
    unvisited = set(range(n))
    parent = {i: -1 for i in range(n)}

    while unvisited:
        current_dist, u = min((distances[*edge] for edge in graph[u] if u in unvisited), default=(float('inf'), -1))

        if current_dist == float('inf'):
            break
        unvisited.remove(u)

        for v, cost in graph[u]:
            dist_to_v = distances[u] + cost
            if dist_to_v < distances[v]:
                distances[v] = dist_to_v
                parent[v] = u
                unvisited.add(v)

    return distances, parent

def detect_rotations(parent):
    cycles = set()
    root = -1
    for node in range(len(parent)):
        path = set()
        x = node
        while x != -1 and x in path:
            path.add(x)
            x = parent[x]

        if root == -1:
            root = node

        if len(path) >= 2 and path.isdisjoint(cycles):
            cycles.add(path)

    rotation = 0
    if root in cycles:
        root = -1
        for cycle in cycles:
            if root in cycle:
                root = cycle.pop(cycle.index(root))
                break
    if root == -1:
        rotations = 0
    else:
        rotation += 1
        while True:
            prev = root
            root = parent[root]
            if root == prev:
                break
            rotation += 1
    return rotation, cycles

def max_possible_turns(parent, rotations, cycles):
    return max(max(len(x) for x in cycles), max(rotation + 1 - len(x) for x, rotation in zip(parent, rotations)))

def tree_game(n, edges, k, starts):
    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append((b, 1))
        graph[b].append((a, 1))

    _, parent = dijsktra(graph, starts[0])
    _, cycles = detect_rotations(parent)

    print(max_possible_turns(parent, len(cycles), list(map(set, cycles))))

    return [0] * n

