            for k in range(node.bit_length(), l, node.bit_length()):
                v |= {k - node.bit_length() * 2**k + 1}
        else:
            node = len(perm) - 1
            while node >= 0 and node & 1:
                v.add(node)
                node >>= 1
            for k in range((node.bit_length()) * 2, l + len(perm) + 1, node.bit_length()):
                v |= {k - (node.bit_length() - 1) - 2**k}
        max_mex = max(find_MEX(perm), find_MEX(perm, sorted(v)[::-1]))
        non_branching_points.update(find_MEX(p, sorted(v)[::-1]) for i, p in enumerate(perm) if 0 <= p < 2**i and 2**i not in v)
        ans = max(ans, max_mex)
    print(ans)

if __name__ == "__main__":
