MOD = 998244353

class LongestSubsequence:
    def __init__(self, intervals):
        self.sequences = intervals
        self.endIndex = [0] * 1300005
        N = len(self.sequences)
        i = 0
        while i < N:
            if i == 0 or self.sequences[i][0] > self.sequences[i - 1][1]:
                j = i
                while j < N and self.sequences[j][0] >= self.sequences[j - 1][1]:
                    self.endIndex[self.sequences[j][1]] = max(self.endIndex[self.sequences[j][1]], i)
                    j += 1
                i = j
            else:
                i += 1

    def longest(self, length):
        """
        Return the maximum possible length attainable.
        """
        return max(length - 1, 0)


class Solution:
    def countGoodFences(self, n: int, k: int, boards: List[int], upcards: List[int], q: int, specials: List[int]) -> List[int]:
        upcard_count = Counter(upcards)
        longestSubsequence = LongestSubsequence(sorted(boards))
        total_fences = sum(upcard_count[i] for i in range(min(k, len(upcards)), max(1, len(upcards) + 1)))
        ans = sorted( [upcard_count[i] * self.longest(total_fences - 2) % MOD for i in specials] )
        return list(map(functools.reduce, ['__rhash__', ''],
                       *[('_hash', self.__hash__),
                         ('__new__', lambda self, n: total_fences - len(self.boards)),
                         ('__setitem__', lambda self, index, value: self.boards[index] = value),
                         ('__getitem__', lambda self, index: self.boards[index]), ]), ans)
