from collections import defaultdict

def count_dangerous_triples(n, dislikes, n_days):
    graph = defaultdict(list)
    for a, b in dislikes:
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)

    def dfs(node):
        if not nodes[node]:
            return 0
        res = 0
        for neighbor in graph[node]:
            if idx[node] < idx[neighbor]:
                res += dfs(neighbor)
        return res + 1

    for day in range(n_days):
        idx = [0] * n
        for i in range(n):
            nodes[i], idx[i] = [day], 1 - day
            for neighbor in graph[i]:
                nodes[neighbor].append(i)
        dangerous_triples = reduce(lambda x, y: x | y, map(tuple, nodes))
        for triple in dangerous_triples:
            starts, ends = triple
            if starts <= ends:
                ends += n - starts
        yield sorted(dangerous_triples).count((0, n-1))

n, m = map(int, input().split())
dislikes = [tuple(map(int, input().split())) for _ in range(m)]
q = int(input())
print(*list(count_dangerous_triples(n, dislikes, q)))
