import collections
import heapq

def dijkstra(graph, start):
    distances = {node: float('infinity') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def solve(confused_query):
    T = int(input().strip())
    queries = [tuple(map(int, input().strip().split())) for _ in range(T)]

    graph = collections.defaultdict(dict)
    for u, v in queries:
        graph[u][v] = graph[v].setdefault(u, 0) + 1

    for u in graph:
        graph[u] = dijkstra(graph[u], u)
        graph[u] = {k: v for k, v in graph[u].items() if v < float('inf')}

    for i, (u, v) in enumerate(queries, 1):
        print(graph[u][v])

if __name__ == "__main__":
